proc routeSensorModule[T](instance: T, bare: string, params: openArray[byte]): Result[seq[byte], InvocationFailure] =
  mixin `configure`, `snapshot`
  let request = ?kitValidator().checkedRequest(bare, params)
  if bare == "configure":
    let response = ?`configure`(instance, fromChecked(SensorNSControlConfigureRequest, request))
    return encodedResponse(encode(response))
  if bare == "snapshot":
    let response = ?`snapshot`(instance, fromChecked(MetricsProviderSnapshotRequest, request))
    return encodedResponse(encode(response))
  discard request
  err(failure(ecMethodNotFound, "unknown method " & bare))

template exportSensorModule*(T: typedesc) =
  ## Defines `sensor_module`'s exported symbols over the handlers of `T`.
  proc sensorModuleKitCreate(init: ModuleInit): Result[pointer, InvocationFailure] {.nimcall, gcsafe, raises: [].} =
    let r = initModule(T, init)
    if r.isErr:
      return err(r.error)
    let instance = r.get
    if instance.isNil:
      return err(moduleError("initModule returned nil"))
    GC_ref(instance)
    ok(cast[pointer](instance))

  proc sensorModuleKitDispose(p: pointer) {.nimcall, gcsafe, raises: [].} =
    let instance {.cursor.} = cast[T](p)
    when compiles(destroyModule(instance)):
      destroyModule(instance)
    GC_unref(instance)

  proc sensorModuleKitName(): cstring {.exportc: "logos_sensor_module_MODULE_name", dynlib, cdecl, gcsafe, raises: [].} =
    system.cstring(moduleName)

